/**
 * Rendered Observable Plot charts, captured verbatim, for the adapter tests.
 *
 * Every `html` string below is the real output of `Plot.plot()` from
 * `@observablehq/plot` **0.6.17**, with two things removed: the `<style>`
 * element Plot injects to scope its own CSS, and the decorative
 * `*-axis tick` groups whose children are the tick marks rather than their
 * labels. Nothing else is edited — the mark groups, the tick *labels*, the
 * axis labels, and every coordinate are exactly what Plot drew.
 *
 * Capturing the markup rather than depending on the package is deliberate.
 * The adapter's contract is with Plot's rendered output, so a fixture that
 * cannot drift from what a test asserts is the point: if a future Plot
 * changes the DOM, these tests keep passing and the adapter keeps working on
 * the version they describe, and the drift is found by re-capturing rather
 * than by a suite that quietly rewrote its own expectations.
 *
 * `scales` records what `plot.scale(name)` returned for the same chart.
 * {@link mountFixture} rebuilds the `apply` and `invert` functions from it,
 * because those are closures and do not serialize.
 *
 * `samples` is the other thing that cannot survive being written down: Plot
 * binds each mark's datum indices to the element as `__data__`, and markup has
 * nowhere to keep them. A fixture that states a count gets them back, which is
 * what lets a test reach the checks that compare a path's vertices against how
 * many samples there should be. A fixture that states none is mounted exactly
 * as before.
 */

/** A scale as `plot.scale()` describes it, minus the functions. */
export interface FixtureScaleSpec {
  type: string;
  domain: (string | number)[];
  /** Pixel endpoints, or — for an ordinal colour scale — the colours. */
  range?: (string | number)[];
  bandwidth?: number;
  step?: number;
  /**
   * A `pow` scale's exponent, which Plot reports alongside its type — 0.5 for
   * the square-root scale it sizes a radius with. Without it the rebuild below
   * would invert a radius linearly and hand back counts the chart never held.
   */
  exponent?: number;
  /** Pixel start of each band, for band scales. */
  positions?: number[];
  /** Colour of each domain value, for ordinal colour scales. */
  colors?: string[];
}

/** One captured chart. */
export interface Fixture {
  html: string;
  scales: Record<string, FixtureScaleSpec>;
  /**
   * How many samples each mark path was drawn from, when the fixture is one
   * whose reading depends on it. Restored onto the path as the datum indices
   * Plot binds there.
   */
  samples?: number;
}

